/**
 * jargon-glossary.js
 * ==================
 * Page-specific logic for the Cohort Study Jargon page: search, category
 * filtering, table rendering, and deep-link scroll/highlight when arriving
 * from a #jargon-<slug> link generated by jargon-linker.js on another page.
 *
 * Depends on jargon-loader.js having already run (for window.NSHD_JARGON_READY).
 * Include on the glossary page, after jargon-loader.js:
 *
 *   <script src="{{ site.baseurl }}/assets/js/jargon-loader.js"></script>
 *   <script src="{{ site.baseurl }}/assets/js/jargon-glossary.js"></script>
 *
 * Falls back to its own fetch if jargon-loader.js isn't present, so this
 * file still works standalone if ever needed.
 */

document.addEventListener("DOMContentLoaded", function () {

  var jargBody = document.getElementById("jargBody");
  if (!jargBody) return; // not on the glossary page

  var catColors = {
    "Study design":         "badge-study",
    "Variables & data":     "badge-var",
    "OWL Metadata":         "badge-meta",
    "Showcase Metadata":    "badge-show",
    "Access & governance":  "badge-access",
    "Navigation":           "badge-nav",
    "Platforms":            "badge-plat",
    "Writing documentation":"badge-write"
  };

  var activeFilter = "";
  var searchVal    = "";
  var TERMS        = [];

  // Matches the slug logic in jargon-loader.js, so a term links to the
  // same #jargon-<slug> anchor whether generated here or by the sitewide
  // jargon-linker.js on another page. jargon-loader.js already computes
  // this per term, but we recompute defensively in case TERMS came from
  // the fallback fetch below (which doesn't add .slug).
  function slugify(str) {
    return (str || "")
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-+|-+$/g, "");
  }

  function escapeHtml(str) {
    return (str || "")
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");
  }

  function render() {
    var noRes = document.getElementById("jargNoResults");
    var count = document.getElementById("jargCount");

    var q       = searchVal.toLowerCase().trim();
    var visible = 0;
    jargBody.innerHTML = "";

    TERMS.forEach(function (t) {
      var matchCat  = !activeFilter || t.cat === activeFilter;
      var matchText = !q || t.term.toLowerCase().indexOf(q) !== -1 || t.def.toLowerCase().indexOf(q) !== -1;
      if (!matchCat || !matchText) return;

      var row = document.createElement("tr");
      row.className = "jarg-row-" + (visible % 7);
      row.id = "jargon-" + (t.slug || slugify(t.term));
      row.innerHTML =
        '<td><span class="term-name"><i class="ti ' + (t.icon || "ti-circle") + '" aria-hidden="true"></i>' +
        escapeHtml(t.term) + '</span></td>' +
        '<td><span class="cat-pill ' + (catColors[t.cat] || "badge-all") + '">' + escapeHtml(t.cat) + '</span></td>' +
        '<td>' + escapeHtml(t.def) + '</td>';
      jargBody.appendChild(row);
      visible++;
    });

    if (noRes) noRes.style.display = visible === 0 ? "block" : "none";
    if (count) count.textContent   = "Showing " + visible + " of " + TERMS.length + " terms";
  }

  // Deep-link handling: someone arriving from another page via
  // #jargon-<slug> hits this page before TERMS finishes loading, so the
  // browser's native hash-scroll fires too early — the row doesn't exist
  // yet — and silently finds nothing. Run this manually once the table
  // has actually been rendered.
  function scrollToHash() {
    if (!window.location.hash) return;
    var target = document.querySelector(window.location.hash);
    if (!target) return;
    requestAnimationFrame(function () {
      target.scrollIntoView({ behavior: "smooth", block: "center" });
      target.classList.add("jarg-row-flash");
      setTimeout(function () { target.classList.remove("jarg-row-flash"); }, 1800);
    });
  }

  var searchEl = document.getElementById("jargSearch");
  if (searchEl) {
    searchEl.addEventListener("input", function () {
      searchVal = this.value;
      render();
    });
  }

  window.setFilter = function (el) {
    var cat = el.getAttribute("data-cat");
    document.querySelectorAll(".jarg-badge").forEach(function (b) { b.classList.remove("active"); });
    document.querySelectorAll(".jarg-cat-link").forEach(function (a) { a.classList.remove("active"); });
    el.classList.add("active");
    var sidebarLink = document.querySelector('.jarg-cat-link[data-cat="' + cat + '"]');
    if (sidebarLink) sidebarLink.classList.add("active");
    activeFilter = cat;
    render();
  };

  window.clearSearch = function () {
    var s = document.getElementById("jargSearch");
    if (s) s.value = "";
    searchVal = "";
    render();
  };

  document.querySelectorAll(".jarg-cat-link").forEach(function (a) {
    a.addEventListener("click", function (e) {
      e.preventDefault();
      var cat   = this.getAttribute("data-cat");
      var badge = document.querySelector('.jarg-badge[data-cat="' + cat + '"]');
      if (badge) window.setFilter(badge);
    });
  });

  function onTermsLoaded(data) {
    TERMS = data.slice().sort(function (a, b) { return a.term.localeCompare(b.term); });
    render();
    scrollToHash();
  }

  function onLoadError(err) {
    var count = document.getElementById("jargCount");
    jargBody.innerHTML = '<tr><td colspan="3" style="padding:20px;color:#777;text-align:center;">' +
      'Glossary data could not be loaded. Make sure <code>/OWL/assets/data/cohort_jargon/jargon-terms.json</code> exists and is valid JSON. (' +
      (err && err.message ? err.message : "unknown error") + ')</td></tr>';
    if (count) count.textContent = "";
  }

  if (window.NSHD_JARGON_READY) {
    // Reuse the sitewide fetch from jargon-loader.js — no duplicate request.
    window.NSHD_JARGON_READY.then(function (data) {
      if (!Array.isArray(data) || data.length === 0) return onLoadError(new Error("Empty or invalid data"));
      onTermsLoaded(data);
    }).catch(onLoadError);
  } else {
    // Fallback: jargon-loader.js wasn't found on this page, fetch directly.
    fetch("/OWL/assets/data/cohort_jargon/jargon-terms.json")
      .then(function (res) {
        if (!res.ok) throw new Error("HTTP " + res.status);
        return res.json();
      })
      .then(function (data) {
        if (!Array.isArray(data) || data.length === 0) throw new Error("Empty or invalid data");
        onTermsLoaded(data);
      })
      .catch(onLoadError);
  }

});